 "beea38c4ab752d": {
  "description": "Return day and moving_avg: the average revenue of the current day and the two days before it (fewer rows at the start), rounded to 2 decimals, ordered by day. Write a single SQLite query. Put CREATE TABLE and INSERT statements in the test case Input; the Expected output is the JSON array of result rows.",
  "testCases": [
   {
    "input": "CREATE TABLE daily_sales (day TEXT PRIMARY KEY, revenue INTEGER);\nINSERT INTO daily_sales VALUES ('2025-03-01',10),('2025-03-02',20),('2025-03-03',30),('2025-03-04',40),('2025-03-05',50);",
    "expected": "[{\"day\":\"2025-03-01\",\"moving_avg\":10},{\"day\":\"2025-03-02\",\"moving_avg\":15},{\"day\":\"2025-03-03\",\"moving_avg\":20},{\"day\":\"2025-03-04\",\"moving_avg\":30},{\"day\":\"2025-03-05\",\"moving_avg\":40}]"
   },
   {
    "input": "CREATE TABLE daily_sales (day TEXT PRIMARY KEY, revenue INTEGER);\nINSERT INTO daily_sales VALUES ('2025-03-01',7);",
    "expected": "[{\"day\":\"2025-03-01\",\"moving_avg\":7}]"
   }
  ],
  "referenceSql": "SELECT day, ROUND(AVG(revenue) OVER (ORDER BY day ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS moving_avg FROM daily_sales ORDER BY day;"
 },
