 "435f758297b5a4": {
  "description": "Return user_id (once each, ascending) of users who logged in on at least 3 consecutive calendar days. Duplicate rows for a day count once. Write a single SQLite query. Put CREATE TABLE and INSERT statements in the test case Input; the Expected output is the JSON array of result rows.",
  "testCases": [
   {
    "input": "CREATE TABLE logins (user_id INTEGER, login_date TEXT);\nINSERT INTO logins VALUES (1,'2025-04-01'),(1,'2025-04-02'),(1,'2025-04-03'),(1,'2025-04-03'),(2,'2025-04-01'),(2,'2025-04-03'),(2,'2025-04-04'),(3,'2025-04-10'),(3,'2025-04-11'),(3,'2025-04-12'),(3,'2025-04-13');",
    "expected": "[{\"user_id\":1},{\"user_id\":3}]"
   },
   {
    "input": "CREATE TABLE logins (user_id INTEGER, login_date TEXT);\nINSERT INTO logins VALUES (9,'2025-05-01'),(9,'2025-05-03');",
    "expected": "[]"
   }
  ],
  "referenceSql": "WITH d AS (SELECT DISTINCT user_id, login_date FROM logins), g AS (SELECT user_id, login_date, date(login_date, '-' || (ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date) - 1) || ' day') AS grp FROM d) SELECT DISTINCT user_id FROM g GROUP BY user_id, grp HAVING COUNT(*) >= 3 ORDER BY user_id;"
 },
